pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash) public {
        // 1. Deploy an adversarial helper that reverts on receive to prevent ether loss on transfer
        Reverter reverter = new Reverter();
        // 2. Lock in a guess as the reverter, so the contract holds ether and settle can be triggered
        vm.deal(address(reverter), 1 ether);
        vm.prank(address(reverter));
        c.lockInGuess{value: 1 ether}(hash);
        // 3. Advance to the settlement block for the reference (block.number + 1)
        vm.roll(block.number + 2);
        // 4. Record balance before settlement
        uint256 balanceBefore = address(reverter).balance;
        // 5. Settle
        vm.prank(address(reverter));
        try c.settle() { } catch { }
        // 6. Compute the expected block hash the reference would use
        bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(block.number - 1)));
        uint256 expectedGain = (hash == expectedAnswer) ? 2 ether : 0;
        // 7. Assert: actual balance gain equals expected gain
        uint256 actualGain = address(reverter).balance - balanceBefore;
        assertTrue(actualGain == expectedGain);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

