pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        payable(address(c)).transfer(0); // silence unused variable
        // Deploy with 1 ether as required by constructor
        c = new C{value: 1 ether}();
        // Ensure the contract has exactly 1 ether
        assertEq(address(c).balance, 1 ether);
    }

    function testFuzz_property(address actor, bytes32 guessArg) public {
        // actor must be distinct from this test contract
        vm.assume(actor != address(this));
        // Provide 1 ether to the actor
        vm.deal(actor, 1 ether);

        // Choose a block number we'll later set as past block
        uint256 targetBlock = 12345;

        // Prank as actor and call lockInGuess with the exact hash of the future blockhash
        vm.prank(actor);
        // We first need to compute what the blockhash WILL be at targetBlock.
        // Since blockhash(targetBlock) in a test is accessible, we can precompute.
        // The actor provides guessArg as the guess.
        // We'll later set block.number > targetBlock and verify settlement.
        // But the interesting property: after settle, if guess matches, actor gets 2 ether.
        // In the mutant, the stored guess is keccak256(guessArg), so even if guessArg == blockhash,
        // the stored guess won't match.

        // Warp block to just before targetBlock
        vm.roll(targetBlock - 1);

        // lockInGuess with guessArg as guess
        uint256 snapshot = vm.snapshot();
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessArg);

        // Now we need a blockhash that equals guessArg.
        // We can't control the blockhash, but we can make the guessArg be the actual blockhash of targetBlock.
        // So let's revert and compute guessArg = blockhash(targetBlock) and pass it.
        vm.revertTo(snapshot);
        // Instead, we'll compute the blockhash of targetBlock first.
        // We need targetBlock to be mined in the test, or we can just use a known blockhash from a fixed block.
        // Alternatively, we can set block.number and use blockhash of a recent block.
        // Simpler: mine 256 blocks, then targetBlock = block.number - 256, then blockhash is zero.
        // That's messy. Better: We'll set block.number to targetBlock and then use the blockhash of that block.
        // vm.roll sets block.number but not blockhash; forge-std test provides cheat to set blockhash? No.
        // Actually, we can't set blockhash. But we can observe the difference via balance: if actor provides guessArg,
        // and the mutant stores hash(guessArg), then even if guessArg matches the eventual blockhash, the settle
        // will fail to pay out. So we can check that the balance of the contract is 0 after settle IF we somehow
        // ensure the guessArg equals the blockhash.
        // Since we can't make guessArg equal blockhash of a future block (we don't control it),
        // we can instead rely on the fact that the mutant always stores a wrong guess, so it will NEVER pay out,
        // while the original will pay out if guessArg == blockhash(targetBlock).
        // To test the property universally, we can't force a specific blockhash, but we can fuzz the scenario
        // and check that if guessArg == blockhash(targetBlock) then balance must become 0 (original pays),
        // and the mutant will fail to pay (balance stays 1).
        // So we need to pick a block whose blockhash is guessArg. We'll make guessArg be the blockhash of targetBlock
        // by first computing it. But targetBlock must be a mined block. We'll just use a block that we know.
        // This is a known problem in Foundry: we can't set blockhash. But we can use a block that already has a hash.
        // We'll use a fixed block number, say 1, whose blockhash is predictable in the test environment? Not reliably.

        // Alternative: The property can be about the stored guess itself? But those were tried.
        // The requirement says: do not repeat the previously tried approaches.
        // Those approaches directly compared stored guess == guessArg.
        // Our rule is about the balance outcome after settle.
        // To make the settle condition true (guess == blockhash), we need to ensure guess equals the blockhash of the block we locked.
        // We can lock in guess = blockhash(block.number) (current block's hash) and then make block.number > that block.
        // Note: blockhash(block.number) is always zero? Actually, in EVM, blockhash(block.number) returns zero because you can't get the current block's hash.
        // But we can lock with guess = bytes32(0), and then hope that a future blockhash is zero? That's unreliable because blockhash is only zero for blocks > 256 in the past.

        // Let's use the fact that blockhash of block.number - 1 is available.
        // So: vm.roll(someBlock); then we mine one block (or just use block.number - 1's hash).
        // We'll set block.number to targetBlock, then lock with guess = blockhash(targetBlock-1).
        // Then set block.number to targetBlock+1, and settle.

        // Implementation:
        vm.roll(targetBlock);
        bytes32 pastBlockhash = blockhash(targetBlock - 1);
        vm.assume(pastBlockhash != bytes32(0)); // ensure it's a valid blockhash

        // Now actor locks with guess = pastBlockhash
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(pastBlockhash);

        // Move past the lock block
        vm.roll(targetBlock + 1);

        // Now actor calls settle
        vm.prank(actor);
        c.settle();

        // After settle, if the guess matched (original), actor got 2 ether, so contract balance is 0.
        // If the guess didn't match (mutant stored hash(pastBlockhash) != pastBlockhash), contract balance remains 1 ether.
        // Assert that the contract balance is 0 (original behavior) but for mutant it will be 1 ether.
        assertTrue(address(c).balance == 0);
    }
}

