pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockDelay) public {
        // blockDelay must be < 1 (i.e. 0) so settle is attempted too early
        blockDelay = bound(blockDelay, 0, 0);

        address actor = address(0x1234);
        bytes32 guessHash = keccak256("guess");

        // fund constructor and lockInGuess with 1 ether each
        vm.deal(actor, 2 ether);
        vm.startPrank(actor);
        (bool ok, ) = address(c).call{value: 1 ether}("");
        require(ok, "constructor payment");
        c.lockInGuess{value: 1 ether}(guessHash);

        // advance by blockDelay blocks (always 0) and try to settle
        vm.roll(block.number + blockDelay);

        // settle must revert because block.number has not passed guesses[msg.sender].block + 1
        bool reverted = false;
        try c.settle() {
        } catch {
            reverted = true;
        }
        vm.stopPrank();

        // The reference must revert (reverted == true).
        // The bug leaves guesses[msg.sender].block == 0, so settle reaches
        // blockhash(0) and panics due to arithmetic underflow/overflow in
        // blockhash(0) or transfer, which still reverts, but for a different reason.
        // However, the property being tested is that settle MUST revert when
        // called before at least one block has passed.
        // In the bug, guesses[msg.sender].block is 0, so block.number > 0 (always true)
        // and settle proceeds, attempting blockhash(0) which is zero; the guess
        // comparison fails and no payment is made, so settle does NOT revert.
        // => The bug violates the rule by NOT reverting.
        assertTrue(reverted);
    }
}

