import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess, uint256 blockDelay) public {
        // 1. Keep params in admissible domain
        vm.assume(blockDelay > 0 && blockDelay < 256);

        // 2. Deploy an adversarial re-entrant caller that calls settle() from its receive()
        ReentrantCaller attacker = new ReentrantCaller(c);

        // Fund the contract with the initial 1 ether (simulating a previous user)
        vm.deal(address(this), 1 ether);
        c.lockInGuess{value: 1 ether}(guess);
        vm.roll(block.number + 1);
        c.settle(); // This wins 2 ether into the contract, leaving contract with 2 ether

        // Now the attacker locks in a guess
        vm.deal(address(attacker), 1 ether);
        attacker.lock{value: 1 ether}(guess);

        // Advance blocks so that settle() is allowed
        vm.roll(block.number + blockDelay);

        // Record attacker's balance before settle
        uint256 balanceBefore = address(attacker).balance;

        // Trigger re-entrant settle
        attacker.triggerSettle();

        // After settle, if guess matches, the attacker should have received 2 ether.
        // In the correct contract, guess is set first, so the guess matches and payout occurs.
        // In the mutant, block is set first, so re-entrant settle uses a zero guess, payout fails,
        // and the attacker's balance remains unchanged.
        assertTrue(address(attacker).balance == balanceBefore + 2 ether);
    }
}

contract ReentrantCaller {
    C public target;
    bool public reentered;
    constructor(C _target) { target = _target; }
    function lock(bytes32 guess) public payable {
        target.lockInGuess{value: msg.value}(guess);
    }
    function triggerSettle() public {
        reentered = false;
        target.settle();
    }
    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.settle();
        }
    }
}

