    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, bytes32 answer) public {
        // Deploy re-entrant attacker
        Attacker attacker = new Attacker(c, answer);
        vm.deal(address(attacker), 1 ether);
        vm.deal(address(c), 1 ether); // Ensure c can pay out 2 ether

        // Attacker calls lockInGuess; during lockInGuess the attacker re-enters settle
        vm.prank(address(attacker));
        attacker.attack{value: 1 ether}(hash);

        // After attack, attacker balance should be 2 ether in reference (guess was correct),
        // but 0 in mutant because guess was zero during re-entrant settle.
        assertTrue(address(attacker).balance == 2 ether);
    }
}

contract Attacker {
    C public c;
    bytes32 answer;
    bool entered;

    constructor(C _c, bytes32 _answer) {
        c = _c;
        answer = _answer;
    }

    function attack(bytes32 hash) external payable {
        entered = false;
        c.lockInGuess{value: 1 ether}(hash);
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            // After block is set but before guess is set in mutant,
            // settle uses zero guess; in reference guess already set.
            c.settle();
        }
    }
}
